CREATE TABLE t1(a NOT NULL,b NOT NULL DEFAULT 5,c NOT NULL ON CONFLICT REPLACE DEFAULT 6,d NOT NULL ON CONFLICT IGNORE DEFAULT 7,e NOT NULL ON CONFLICT ABORT DEFAULT 8); CREATE INDEX t1a ON t1(a); CREATE INDEX t1b ON t1(b); CREATE INDEX t1c ON t1(c); CREATE INDEX t1d ON t1(d); CREATE INDEX t1e ON t1(e); CREATE INDEX t1abc ON t1(a,b,c);